description:
Implement `DeepPartial<T>` — a recursive type that makes all properties optional at every depth level.

**Example:**
```ts
type Config = DeepPartial<{ host: string; db: { port: number; name: string } }>;
// { host?: string; db?: { port?: number; name?: string } }
```

starter_code:
export type DeepPartial<T> = // your type here

export function mergeConfig<T>(defaults: T, overrides: DeepPartial<T>): T {
  return { ...defaults, ...overrides } as T;
}

test_suite:
test('mergeConfig merges top-level overrides', () => {
  const defaults = { host: 'localhost', port: 5432 };
  const result = mergeConfig(defaults, { port: 3000 });
  expect(result.port).toBe(3000);
  expect(result.host).toBe('localhost');
});

test('type-level: top-level props are optional', () => {
  type T = DeepPartial<{ a: number; b: string }>;
  type Check = T extends { a?: number; b?: string } ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

test('type-level: nested props are optional', () => {
  type T = DeepPartial<{ inner: { x: number } }>;
  type Check = T extends { inner?: { x?: number } } ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

test('type-level: primitives pass through', () => {
  type T = DeepPartial<string>;
  const check: T = 'hello';
  expect(check).toBe('hello');
});

// __hidden__
test('type-level: matches Partial at top level', () => {
  type T = { name: string; age: number };
  type Check = DeepPartial<T> extends Partial<T> ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

solution:
export type DeepPartial<T> = T extends object ? { [K in keyof T]?: DeepPartial<T[K]> } : T;

export function mergeConfig<T>(defaults: T, overrides: DeepPartial<T>): T {
  return { ...defaults, ...overrides } as T;
}
